package main

import (
	"fmt"
	"regexp"
)

var defaultGenerateArgs = []string{"--abi", strconv.Itoa(maxABI)}

var cliVersionPattern = regexp.MustCompile(`\b\d+\.\d+\.\d+\b`)

// wantsGeneration reports whether this run regenerates the parser.
func wantsGeneration(existing Grammar, o options) bool {
	return o.Generate || o.TreeSitterCLI != "" || (existing.LocalBuild != nil && existing.LocalBuild.TreeSitterCLI != "")
}

// cliVersion picks the tree-sitter-cli to run: an explicit override, else
// the recorded version when regenerating the recorded revision (so the
// output is reproducible), else latest.
func cliVersion(existing Grammar, revision string, o options) string {
	if o.TreeSitterCLI != "" {
		return o.TreeSitterCLI
	}
	if existing.LocalBuild != nil && existing.LocalBuild.TreeSitterCLI != "" && existing.Revision == revision {
		return existing.LocalBuild.TreeSitterCLI
	}
	return "latest"
}

func generateArgs(build *LocalBuild) []string {
	if build != nil && len(build.GenerateArgs) > 0 {
		return build.GenerateArgs
	}
	return defaultGenerateArgs
}

// resolveCLI turns a version spec such as "latest" into the exact version
// npx runs, so generation and the manifest use the same one.
func resolveCLI(dir, spec string) (string, error) {
	out, err := npx(dir, "tree-sitter-cli@"+spec, "--version")
	if err != nil {
		return "", fmt.Errorf("tree-sitter-cli@%s --version: %w", spec, err)
	}
	version := cliVersionPattern.FindString(out)
	if version == "" {
		return "", fmt.Errorf("tree-sitter-cli@%s --version printed no version: %q", spec, out)
	}
	return version, nil
}

func generate(grammarRoot, version string, args []string) error {
	if _, err := npx(grammarRoot, append([]string{"tree-sitter-cli@" + version, "generate"}, args...)...); err != nil {
		return fmt.Errorf("tree-sitter-cli@%s generate: %w; if this release cannot generate ABI %d, pass -tree-sitter-cli <older version>", version, err, maxABI)
	}
	return nil
}

// Command grammar-refresh vendors a tree-sitter grammar into
// internal/sem/grammars/<lang> from its upstream git repository and records
// where it came from in internal/sem/grammars/grammars.json. It is a
// maintainer tool: it needs the network, and its output is committed, so
// building entire-graph never downloads anything.
//
// Usage:
//
//	go run ./cmd/grammar-refresh -lang zig -ref v1.1.2
//	go run ./cmd/grammar-refresh -lang fsharp -ref <commit> -path fsharp -allow-local-changes
//	go run ./cmd/grammar-refresh -lang newlang -ref v1.0.0 -url https://github.com/o/tree-sitter-newlang
//	go run ./cmd/grammar-refresh -lang rust -ref v0.24.2 -url https://github.com/tree-sitter/tree-sitter-rust -generate
//	go run ./cmd/grammar-refresh -lang csharp -ref v0.24.0 -tree-sitter-cli 0.26.7
//
// The vendored src/parser.c must be ABI 13-14, the range the go-tree-sitter
// runtime loads. A manifest entry's local_build block, or -generate, builds it
// instead of copying it: the entry's patch is applied to the checkout, then
// `npx tree-sitter-cli@<version> generate <args>` runs (default --abi 14),
// which needs Node.js. The recorded revision regenerates with the recorded
// version; a new revision uses @latest and records the version it ran.
// -tree-sitter-cli pins one, which is the fix if a future tree-sitter release
// stops generating ABI 14. binding.go is never touched, so
// a new language still needs one. A grammar that changes parse results needs
// an IdentityRevision bump (internal/sem/provider.go) in the same commit.
//
// A manifest entry with local_changes carries edits that upstream does not
// have, and copying upstream verbatim would discard them. The tool refuses
// such a grammar unless -allow-local-changes is passed, and the maintainer then
// reapplies the steps in the entry's note. Notes survive every refresh.
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
)

func main() {
	var (
		lang         = flag.String("lang", "", "grammar directory name under -dir (required)")
		ref          = flag.String("ref", "", "tag, branch or full commit to vendor (required)")
		url          = flag.String("url", "", "git URL; defaults to the manifest entry")
		subdir       = flag.String("path", "", "grammar subdirectory within the repository; defaults to the manifest entry")
		manifestPath = flag.String("manifest", "internal/sem/grammars/grammars.json", "path to the grammar manifest")
		grammarsDir  = flag.String("dir", "internal/sem/grammars", "directory holding vendored grammars")
		allowLocal   = flag.Bool("allow-local-changes", false, "overwrite a grammar whose manifest entry records local changes; they must then be reapplied by hand")
		generateFlag = flag.Bool("generate", false, "regenerate the parser with tree-sitter-cli (via npx) even if the manifest entry records no local build")
		cliFlag      = flag.String("tree-sitter-cli", "", "tree-sitter-cli version to generate with; implies -generate")
	)
	flag.Parse()
	if *lang == "" || *ref == "" {
		flag.Usage()
		os.Exit(2)
	}
	o := options{
		Lang:              *lang,
		Ref:               *ref,
		URL:               *url,
		Subdir:            *subdir,
		ManifestPath:      *manifestPath,
		GrammarsDir:       *grammarsDir,
		AllowLocalChanges: *allowLocal,
		Generate:          *generateFlag,
		TreeSitterCLI:     *cliFlag,
	}
	if err := refresh(o); err != nil {
		fmt.Fprintln(os.Stderr, "grammar-refresh:", err)
		os.Exit(1)
	}
}

var languageNamePattern = regexp.MustCompile(`^[a-z0-9_]+$`)

// options holds one run's settings. An empty URL or Subdir falls back to the
// manifest entry.
type options struct {
	Lang, Ref, URL, Subdir    string
	ManifestPath, GrammarsDir string
	AllowLocalChanges         bool
	// Generate regenerates the parser even when the entry records no
	// tree-sitter-cli; TreeSitterCLI overrides the version chosen.
	Generate      bool
	TreeSitterCLI string
}

func refresh(o options) error {
	lang, ref, url, subdir := o.Lang, o.Ref, o.URL, o.Subdir
	manifestPath, grammarsDir := o.ManifestPath, o.GrammarsDir
	if !languageNamePattern.MatchString(lang) {
		return fmt.Errorf("invalid -lang %q: use the lower-case directory name under %s", lang, grammarsDir)
	}
	if subdir != "" && !filepath.IsLocal(subdir) {
		return fmt.Errorf("invalid -path %q: must be a relative path inside the repository", subdir)
	}
	grammars, err := loadManifest(manifestPath)
	if err != nil {
		return err
	}
	var existing Grammar
	for _, g := range grammars {
		if g.Language == lang {
			existing = g
		}
	}
	if url == "" {
		url = existing.URL
	}
	if url == "" {
		return fmt.Errorf("%s is not in %s; pass -url", lang, manifestPath)
	}
	if subdir == "" {
		subdir = existing.Path
	}
	if subdir != "" && !filepath.IsLocal(subdir) {
		return fmt.Errorf("invalid path %q for %s in %s: must be a relative path inside the repository", subdir, lang, manifestPath)
	}
	if existing.LocalChanges && !o.AllowLocalChanges {
		return fmt.Errorf("%s has local changes that a verbatim refresh would discard (%s); pass -allow-local-changes to overwrite it, then reapply them by hand", lang, existing.Note)
	}
	build := existing.LocalBuild
	var patchFile string
	if build != nil && build.Patch != "" {
		if !filepath.IsLocal(build.Patch) {
			return fmt.Errorf("invalid patch %q for %s in %s: must be a relative path inside %s", build.Patch, lang, manifestPath, grammarsDir)
		}
		if patchFile, err = filepath.Abs(filepath.Join(grammarsDir, build.Patch)); err != nil {
			return err
		}
	}
	generating := wantsGeneration(existing, o)
	if generating {
		if err := findNPX(); err != nil {
			return err
		}
	}

	tmp, err := os.MkdirTemp("", "grammar-refresh-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmp)
	if err := git(tmp, "init", "-q"); err != nil {
		return err
	}
	if err := git(tmp, "fetch", "-q", "--depth", "1", "--", url, ref); err != nil {
		return fmt.Errorf("fetch %s %s: %w", url, ref, err)
	}
	if err := git(tmp, "checkout", "-q", "FETCH_HEAD"); err != nil {
		return err
	}
	revision, err := gitOutput(tmp, "rev-parse", "HEAD")
	if err != nil {
		return err
	}
	if patchFile != "" {
		if err := applyPatch(tmp, subdir, patchFile); err != nil {
			return fmt.Errorf("%s at %s: %w", url, ref, err)
		}
	}
	var version string
	if generating {
		grammarRoot := filepath.Join(tmp, subdir)
		if version, err = resolveCLI(grammarRoot, cliVersion(existing, revision, o)); err != nil {
			return err
		}
		args := generateArgs(build)
		if err := generate(grammarRoot, version, args); err != nil {
			return err
		}
		next := LocalBuild{}
		if build != nil {
			next = *build
		}
		next.TreeSitterCLI, next.GenerateArgs = version, args
		build = &next
	}

	files, abi, err := vendor(tmp, subdir, filepath.Join(grammarsDir, lang))
	var unsupported abiError
	if generating && errors.As(err, &unsupported) {
		return fmt.Errorf("%s at %s: %w; tree-sitter-cli %s may no longer generate ABI 14, so pass -tree-sitter-cli <older version>", url, ref, err, version)
	}
	if err != nil {
		return fmt.Errorf("%s at %s: %w", url, ref, err)
	}
	grammars = upsert(grammars, Grammar{
		Language:  lang,
		URL:       url,
		Reference: ref,
		Revision:  revision,
		Path:      subdir,
		Files:     files,
		ABI:       abi,
		// Kept across a revision change: that is when a note's manual steps
		// are due. A note the new revision makes obsolete is removed by hand.
		LocalChanges: existing.LocalChanges,
		Note:         existing.Note,
		LocalBuild:   build,
	})
	if err := saveManifest(manifestPath, grammars); err != nil {
		return err
	}
	fmt.Printf("vendored %s %s (%s, ABI %d) into %s\n", lang, ref, revision[:7], abi, filepath.Join(grammarsDir, lang))
	if existing.LocalChanges {
		fmt.Printf("warning: %s now lacks its local changes; reapply them before committing\n", lang)
	}
	if existing.Note != "" {
		fmt.Printf("note: %s\n", existing.Note)
	}
	fmt.Println("next: bump IdentityRevision in internal/sem/provider.go if parse results change, and run scripts/gen-notices.sh")
	return nil
}

func git(dir string, args ...string) error {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

// applyPatch applies patchFile to the grammar at subdir inside checkout; the
// patch's paths are relative to the grammar directory.
func applyPatch(checkout, subdir, patchFile string) error {
	args := []string{"apply"}
	if subdir != "" {
		args = append(args, "--directory="+filepath.ToSlash(subdir))
	}
	args = append(args, "--", patchFile)
	cmd := exec.Command("git", args...)
	cmd.Dir = checkout
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("apply %s: %w\n%s", patchFile, err, strings.TrimSpace(string(out)))
	}
	return nil
}

var errNoNPX = errors.New("tree-sitter generation needs Node.js; npx was not found on PATH")

// npx and findNPX are variables so tests can stand in for Node.
var (
	npx     = runNPX
	findNPX = func() error {
		if _, err := exec.LookPath("npx"); err != nil {
			return errNoNPX
		}
		return nil
	}
)

func runNPX(dir string, args ...string) (string, error) {
	cmd := exec.Command("npx", append([]string{"--yes"}, args...)...)
	cmd.Dir = dir
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	if errors.Is(err, exec.ErrNotFound) {
		err = errNoNPX
	}
	return strings.TrimSpace(string(out)), err
}

func gitOutput(dir string, args ...string) (string, error) {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	return strings.TrimSpace(string(out)), err
}

package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

const (
	minABI = 13
	maxABI = 14
)

// Grammar is one vendored grammar's origin, as recorded in grammars.json.
type Grammar struct {
	Language  string   `json:"language"`
	URL       string   `json:"url"`
	Reference string   `json:"reference"`
	Revision  string   `json:"revision"`
	Path      string   `json:"path,omitempty"`
	Files     []string `json:"files"`
	ABI       int      `json:"abi"`
	// LocalChanges marks vendored files that differ from upstream at Revision
	// in ways a refresh would discard. Note says how to reapply them.
	LocalChanges bool        `json:"local_changes,omitempty"`
	Note         string      `json:"note,omitempty"`
	LocalBuild   *LocalBuild `json:"local_build,omitempty"`
}

// LocalBuild is how grammar-refresh turns the upstream checkout into the
// vendored files: Patch (relative to the grammars directory) is applied
// first, then the parser is regenerated when TreeSitterCLI is set.
type LocalBuild struct {
	Patch         string   `json:"patch,omitempty"`
	TreeSitterCLI string   `json:"tree_sitter_cli,omitempty"`
	GenerateArgs  []string `json:"generate_args,omitempty"`
}

// abiError is a generated parser.c the go-tree-sitter runtime cannot load.
type abiError struct{ abi int }

func (e abiError) Error() string {
	return fmt.Sprintf("grammar is ABI %d, but the go-tree-sitter runtime accepts ABI %d-%d; regenerate it with `tree-sitter generate --abi 14` and vendor the result", e.abi, minABI, maxABI)
}

var languageVersionPattern = regexp.MustCompile(`(?m)^#define LANGUAGE_VERSION (\d+)\s*$`)

func languageABI(parserC []byte) (int, error) {
	m := languageVersionPattern.FindSubmatch(parserC)
	if m == nil {
		return 0, fmt.Errorf("parser.c has no #define LANGUAGE_VERSION")
	}
	return strconv.Atoi(string(m[1]))
}

// vendor copies a generated grammar from repoRoot/subdir into destDir:
// src/parser.c, src/scanner.c when present, src/*.h, src/tree_sitter/*.h and the
// license file as LICENSE (from the grammar directory, else the repository root). Files
// of those kinds already in destDir that the new grammar lacks are removed;
// everything else there, such as binding.go, is left alone. Nothing in destDir
// changes unless the grammar has a parser.c the go-tree-sitter runtime can load.
func vendor(repoRoot, subdir, destDir string) ([]string, int, error) {
	grammarRoot := filepath.Join(repoRoot, subdir)
	parserC, err := os.ReadFile(filepath.Join(grammarRoot, "src", "parser.c"))
	if err != nil {
		return nil, 0, fmt.Errorf("no generated %s (pick a ref that ships generated sources)", filepath.ToSlash(filepath.Join(subdir, "src", "parser.c")))
	}
	abi, err := languageABI(parserC)
	if err != nil {
		return nil, 0, err
	}
	if abi < minABI || abi > maxABI {
		return nil, 0, abiError{abi}
	}

	sources := map[string]string{"parser.c": filepath.Join(grammarRoot, "src", "parser.c")}
	if scanner := filepath.Join(grammarRoot, "src", "scanner.c"); fileExists(scanner) {
		sources["scanner.c"] = scanner
	}
	for _, dir := range []string{"", "tree_sitter/"} {
		headers, err := filepath.Glob(filepath.Join(grammarRoot, "src", filepath.FromSlash(dir), "*.h"))
		if err != nil {
			return nil, 0, err
		}
		for _, h := range headers {
			sources[dir+filepath.Base(h)] = h
		}
	}
	license := findLicense(grammarRoot)
	if license == "" {
		license = findLicense(repoRoot)
	}
	if license == "" {
		return nil, 0, fmt.Errorf("no LICENSE or COPYING file in %s or the repository root", grammarRoot)
	}
	// Always LICENSE: scripts/gen-notices.sh only attributes files by that name.
	sources["LICENSE"] = license

	stale, err := vendoredFiles(destDir)
	if err != nil {
		return nil, 0, err
	}
	for _, rel := range stale {
		if _, keep := sources[rel]; !keep {
			if err := os.Remove(filepath.Join(destDir, filepath.FromSlash(rel))); err != nil {
				return nil, 0, err
			}
		}
	}
	files := make([]string, 0, len(sources))
	for rel, src := range sources {
		data, err := os.ReadFile(src)
		if err != nil {
			return nil, 0, err
		}
		dst := filepath.Join(destDir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
			return nil, 0, err
		}
		if err := os.WriteFile(dst, data, 0o644); err != nil {
			return nil, 0, err
		}
		files = append(files, rel)
	}
	sort.Strings(files)
	return files, abi, nil
}

func fileExists(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

func findLicense(dir string) string {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return ""
	}
	for _, e := range entries {
		name := strings.ToUpper(e.Name())
		if !e.IsDir() && (strings.HasPrefix(name, "LICENSE") || strings.HasPrefix(name, "COPYING")) {
			return filepath.Join(dir, e.Name())
		}
	}
	return ""
}

// vendoredFiles lists the files in destDir that vendor manages.
func vendoredFiles(destDir string) ([]string, error) {
	var out []string
	entries, err := os.ReadDir(destDir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	for _, e := range entries {
		name := e.Name()
		upper := strings.ToUpper(name)
		switch {
		case e.IsDir() && name == "tree_sitter":
			headers, err := filepath.Glob(filepath.Join(destDir, "tree_sitter", "*.h"))
			if err != nil {
				return nil, err
			}
			for _, h := range headers {
				out = append(out, "tree_sitter/"+filepath.Base(h))
			}
		case name == "parser.c" || name == "scanner.c", !e.IsDir() && strings.HasSuffix(name, ".h"),
			strings.HasPrefix(upper, "LICENSE"), strings.HasPrefix(upper, "COPYING"):
			out = append(out, name)
		}
	}
	return out, nil
}

func loadManifest(path string) ([]Grammar, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	var grammars []Grammar
	if err := json.Unmarshal(data, &grammars); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return grammars, nil
}

func saveManifest(path string, grammars []Grammar) error {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(grammars); err != nil {
		return err
	}
	return os.WriteFile(path, buf.Bytes(), 0o644)
}

// upsert replaces the entry for g.Language, or inserts it, keeping the
// manifest sorted by language.
func upsert(grammars []Grammar, g Grammar) []Grammar {
	i := sort.Search(len(grammars), func(i int) bool { return grammars[i].Language >= g.Language })
	if i < len(grammars) && grammars[i].Language == g.Language {
		grammars[i] = g
		return grammars
	}
	grammars = append(grammars, Grammar{})
	copy(grammars[i+1:], grammars[i:])
	grammars[i] = g
	return grammars
}

