package sem

import (
	"bufio"
	"encoding/json"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// Throwaway, untracked: per-file Rust parser audit for the v0.24.2 validation.
func TestRustAudit(t *testing.T) {
	corpus, out := os.Getenv("RUST_AUDIT_CORPUS"), os.Getenv("RUST_AUDIT_OUT")
	if corpus == "" || out == "" {
		t.Skip("set RUST_AUDIT_CORPUS and RUST_AUDIT_OUT")
	}
	f, err := os.Create(out)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	w := bufio.NewWriter(f)
	defer w.Flush()
	enc := json.NewEncoder(w)
	repos := strings.Split(os.Getenv("RUST_AUDIT_REPOS"), ",")
	for _, repo := range repos {
		root := filepath.Join(corpus, repo)
		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() {
				if d.Name() == ".git" {
					return filepath.SkipDir
				}
				return nil
			}
			if !d.Type().IsRegular() || !strings.HasSuffix(path, ".rs") {
				return nil
			}
			info, err := d.Info()
			if err != nil || info.Size() > defaultMaxParseBytes {
				return nil
			}
			src, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			rel, _ := filepath.Rel(root, path)
			entities, _, status := TreeSitterParser{}.ParseWithStatus(rel, string(src))
			keys := make([]string, 0, len(entities))
			for _, e := range entities {
				keys = append(keys, e.Kind+"\t"+e.Name+"\t"+strconv.Itoa(e.StartLine)+"\t"+e.Signature)
			}
			sort.Strings(keys)
			return enc.Encode(map[string]any{
				"repo": repo, "path": filepath.ToSlash(rel),
				"error": status.ParseError, "partial": status.Partial, "symbols": keys,
			})
		})
		if err != nil {
			t.Fatalf("%s: %v", repo, err)
		}
	}
}

